_W26_EN0, _W26_ZH0 = build_wave26_blobs()
WAVE26_KEYS: tuple[str, ...] = tuple(sorted(_W26_EN0))
assert _W26_EN0.keys() == _W26_ZH0.keys(), "wave26 EN/ZH key sets must match"
